var PRICE_IDS = {
  HOBBYIST: undefined,
  PRO: process.env.STRIPE_PRICE_PRO || undefined,
  STUDIO: process.env.STRIPE_PRICE_STUDIO || undefined
};
var TIER_AMOUNTS = {
  PRO: 1999,
  STUDIO: 5999
};
async function ensurePrice(tier) {
  if (PRICE_IDS[tier])
    return PRICE_IDS[tier];
  const products = await stripe.products.list({ active: true, limit: 100 });
  let product = products.data.find((p) => p.name === `StitchWise ${tier}`);
  if (!product) {
    product = await stripe.products.create({
      name: `StitchWise ${tier}`,
      description: tier === "PRO" ? "Unlimited AI generations, machine embroidery exports" : "Commercial licenses, multi-user accounts, bulk processing",
      tax_code: "txcd_10000000"
    });
  } else if (!product.tax_code) {
    product = await stripe.products.update(product.id, {
      tax_code: "txcd_10000000"
    });
  }
  const prices = await stripe.prices.list({
    product: product.id,
    active: true,
    limit: 10
  });
  if (prices.data.length > 0) {
    return prices.data[0].id;
  }
  const price = await stripe.prices.create({
    product: product.id,
    unit_amount: TIER_AMOUNTS[tier],
    currency: "usd",
    recurring: { interval: "month" }
  });
  return price.id;
}
