// src/infrastructure/services/openaiImageService.ts
function getClient() {
  const apiKey = process.env.OPENAI_API_KEY;
  if (!apiKey)
    return null;
  return new OpenAI({ apiKey });
}
async function generateImageWithDallE(prompt, styleHints, userId) {
  const client = getClient();
  if (!client) {
    console.error(JSON.stringify({
      event: "openai_no_key",
      message: "OPENAI_API_KEY not configured \u2014 DALL-E generation skipped"
    }));
    return null;
  }
  const defaultStyle = [
    "a single flat illustration, one complete composition",
    "not tiled, not repeating, not a pattern, not a fabric swatch, not a wallpaper",
    "clean flat illustration style, posterized, solid color regions, no gradients",
    "one clear subject centered and filling the entire frame",
    "clean well-defined shapes, limited palette of distinct colors",
    "white background, no borders, no frames, no text, no labels"
  ].join(", ");
  const enhancedPrompt = styleHints ? `${prompt}, ${styleHints}` : `${prompt}, ${defaultStyle}`;
  const models = ["gpt-image-1", "gpt-image-2"];
  let lastError = null;
  for (const model of models) {
    try {
      console.error(JSON.stringify({
        event: "openai_image_request",
        model,
        originalPrompt: prompt
      }));
      const response = await client.images.generate({
        model,
        prompt: enhancedPrompt,
        n: 1,
        size: "1024x1024"
      });
      let buffer;
      const imageUrl = response.data?.[0]?.url;
      const b64Json = response.data?.[0]?.b64_json;
      if (imageUrl) {
        const dlResponse = await axios_default.get(imageUrl, {
          responseType: "arraybuffer",
          timeout: 30000
        });
        buffer = Buffer.from(dlResponse.data);
      } else if (b64Json) {
        buffer = Buffer.from(b64Json, "base64");
      } else {
        continue;
      }
      logAICall({
        timestamp: new Date().toISOString(),
        provider: "openai",
        model,
        status: "success",
        estimatedCost: getEstimatedCost(model),
        durationMs: 0,
        userId,
        promptPreview: prompt.slice(0, 100)
      });
      const mimeType = "image/png";
      const dataUrl = `data:${mimeType};base64,${buffer.toString("base64")}`;
      return { url: dataUrl, buffer };
    } catch (err) {
      lastError = err?.message || String(err);
      const errorBody = err?.response?.data || err?.error || "no details";
      console.error(JSON.stringify({
        event: "openai_model_error",
        model,
        error: lastError,
        details: String(errorBody).substring(0, 300)
      }));
    }
  }
  console.error(JSON.stringify({
    event: "openai_all_models_failed",
    error: lastError
  }));
  logAICall({
    timestamp: new Date().toISOString(),
    provider: "openai",
    model: "all",
    status: "error",
    estimatedCost: 0,
    durationMs: 0,
    userId,
    promptPreview: prompt.slice(0, 100),
    error: lastError || undefined
  });
  return null;
}

