import sharp3 from "sharp";
function toGrid(n, gridSize) {
  return Math.round(n * (gridSize - 1));
}
function fillCircle(grid, cx2, cy2, radius, color, gridSize) {
  const gcx = toGrid(cx2, gridSize);
  const gcy = toGrid(cy2, gridSize);
  const gr = Math.round(radius * gridSize);
  for (let row = 0;row < gridSize; row++) {
    for (let col = 0;col < gridSize; col++) {
      if ((col - gcx) ** 2 + (row - gcy) ** 2 <= gr ** 2) {
        grid[row][col] = { color };
      }
    }
  }
}
function fillEllipse(grid, cx2, cy2, rx, ry, color, gridSize) {
  const gcx = toGrid(cx2, gridSize);
  const gcy = toGrid(cy2, gridSize);
  const grx = rx * gridSize;
  const gry = ry * gridSize;
  for (let row = 0;row < gridSize; row++) {
    for (let col = 0;col < gridSize; col++) {
      const dx = (col - gcx) / grx;
      const dy = (row - gcy) / gry;
      if (dx * dx + dy * dy <= 1) {
        grid[row][col] = { color };
      }
    }
  }
}
