  bloomDark: "#c2185b",
  bloomMid: "#e91e63",
  bloomLight: "#f06292",
  bloomPale: "#fce4ec",
  center: "#880e4f",
  leafDark: "#2e7d32",
  leafLight: "#4caf50",
  background: "#ffffff"
