function generatePeony(gridSize) {
  const grid = createEmptyGrid(gridSize, gridSize, PEONY.background);
  const cx2 = 0.5;
  const cy2 = 0.42;
  const outerR = 0.32;
  const midR = 0.24;
  const innerR = 0.14;
  const centerR = 0.06;
  for (let row = 0;row < gridSize; row++) {
    for (let col = 0;col < gridSize; col++) {
      const px2 = col / (gridSize - 1);
      const py2 = row / (gridSize - 1);
      const d = Math.sqrt((px2 - cx2) ** 2 + (py2 - cy2) ** 2);
      if (d > outerR)
        continue;
      if (d > outerR - 0.04) {
        const angle = Math.atan2(py2 - cy2, px2 - cx2);
        const petals = 8;
        const petalAngle = angle * petals / (2 * Math.PI);
        const bump = Math.sin(petalAngle * Math.PI * 2) * 0.03;
        if (d > outerR - 0.04 + bump) {
          grid[row][col] = { color: PEONY.bloomMid };
          continue;
        }
      }
      if (d <= midR) {
        if (d <= centerR) {
          grid[row][col] = { color: PEONY.center };
        } else if (d <= innerR) {
          const angle = Math.atan2(py2 - cy2, px2 - cx2);
          const segment = Math.floor((angle + Math.PI) / (2 * Math.PI) * 7);
          grid[row][col] = { color: segment % 2 === 0 ? PEONY.bloomDark : PEONY.bloomMid };
        } else {
          grid[row][col] = { color: PEONY.bloomPale };
        }
      } else if (d <= outerR - 0.08) {
        const angle = Math.atan2(py2 - cy2, px2 - cx2);
        const segment = Math.floor((angle + Math.PI) / (2 * Math.PI) * 10);
        grid[row][col] = { color: segment % 2 === 0 ? PEONY.bloomLight : PEONY.bloomMid };
      } else {
        grid[row][col] = { color: PEONY.bloomDark };
      }
    }
  }
  const leafCy = cy2 + outerR * 0.7;
  fillEllipse(grid, cx2 - 0.15, leafCy + 0.05, 0.12, 0.06, PEONY.leafDark, gridSize);
  fillEllipse(grid, cx2 + 0.15, leafCy + 0.05, 0.12, 0.06, PEONY.leafDark, gridSize);
  fillRect(grid, cx2 - 0.02, leafCy + 0.02, cx2 + 0.02, 0.85, PEONY.leafDark, gridSize);
  return grid;
}
function pointInTriangle(px2, py2, a, b, c) {
  const denom = (b[1] - c[1]) * (a[0] - c[0]) + (c[0] - b[0]) * (a[1] - c[1]);
  if (Math.abs(denom) < 0.0000000001)
    return false;
  const u = ((b[1] - c[1]) * (px2 - c[0]) + (c[0] - b[0]) * (py2 - c[1])) / denom;
  const v = ((c[1] - a[1]) * (px2 - c[0]) + (a[0] - c[0]) * (py2 - c[1])) / denom;
  const w = 1 - u - v;
  return u >= 0 && v >= 0 && w >= 0;
}
function buildPalette(grid) {
  const counts = new Map;
  for (const row of grid) {
    for (const cell of row) {
      const c = cell.color.toLowerCase();
      counts.set(c, (counts.get(c) ?? 0) + 1);
    }
  }
  const entries = Array.from(counts.entries()).filter(([, cnt]) => cnt > 0).sort(([, a], [, b]) => b - a);
  return entries.map(([hex, count]) => {
    const match = hex.replace("#", "").match(/^([a-f0-9]{2})([a-f0-9]{2})([a-f0-9]{2})$/i);
    let dmcCode = hex;
    let dmcName = "Unknown";
    if (match) {
      const r = parseInt(match[1], 16);
      const g = parseInt(match[2], 16);
      const b = parseInt(match[3], 16);
      const closest = closestDmcColor(r, g, b);
      dmcCode = closest.code;
      dmcName = closest.name;
    }
    return { code: dmcCode, name: dmcName, hex, count };
  });
}
