async function renderPatternToPng(grid, gridSize) {
  const pixels = Buffer.alloc(gridSize * gridSize * 3);
  for (let row = 0;row < gridSize; row++) {
    for (let col = 0;col < gridSize; col++) {
      const idx = (row * gridSize + col) * 3;
      const hex = (grid[row]?.[col]?.color || "#ffffff").replace("#", "");
      pixels[idx] = parseInt(hex.slice(0, 2), 16);
      pixels[idx + 1] = parseInt(hex.slice(2, 4), 16);
      pixels[idx + 2] = parseInt(hex.slice(4, 6), 16);
    }
  }
  return sharp3(pixels, {
    raw: { width: gridSize, height: gridSize, channels: 3 }
  }).png().toBuffer();
}
function generateSubjectPattern(prompt, gridSize) {
  const validSizes = AVAILABLE_GRID_SIZES;
  const size = gridSize >= 8 && gridSize <= 200 ? gridSize : 100;
  let matchedEntry = null;
  for (const entry of SUBJECT_REGISTRY) {
    if (entry.patterns.some((p) => p.test(prompt))) {
      matchedEntry = entry;
      break;
    }
  }
  if (!matchedEntry)
    return null;
  const grid = matchedEntry.generator(size);
  const dmcColors = buildPalette(grid).map((c, i) => ({
    ...c,
    symbol: CROSS_STITCH_SYMBOLS[i % CROSS_STITCH_SYMBOLS.length]
  }));
  const stitchCount = dmcColors.reduce((s, c) => s + c.count, 0);
  return {
    grid,
    gridSize: size,
    stitchCount,
    dmcColors,
    prompt
  };
}

// src/infrastructure/middleware/aiRateLimit.ts
import { readFileSync, writeFileSync, mkdirSync as mkdirSync2 } from "fs";
import { dirname, resolve } from "path";
var AI_LIMITS = {
  HOBBYIST: { daily: 5, monthly: 30 },
  PRO: { daily: 30, monthly: 200 },
  STUDIO: { daily: 75, monthly: 500 }
};
var USAGE_FILE = resolve(process.cwd(), "logs/ai-daily-usage.json");
function today() {
  return new Date().toISOString().slice(0, 10);
}
function monthPrefix(date) {
  return date.slice(0, 7);
}
function tierAndLimits(raw) {
  const normalized = (raw ?? "HOBBYIST").toUpperCase();
  const tier = normalized === "PRO CRAFTER" ? "PRO" : normalized === "DESIGN STUDIO" ? "STUDIO" : normalized;
  return { tier, limits: AI_LIMITS[tier] ?? AI_LIMITS.HOBBYIST };
}
function readUsage() {
  try {
    return JSON.parse(readFileSync(USAGE_FILE, "utf8"));
  } catch {
    return {};
  }
}
function writeUsage(usage) {
  mkdirSync2(dirname(USAGE_FILE), { recursive: true });
  writeFileSync(USAGE_FILE, JSON.stringify(usage, null, 2) + `
`);
}
function currentUsage(usage, date, userId) {
  const month = monthPrefix(date);
  let monthly = 0;
  for (const [key, users] of Object.entries(usage)) {
    if (key.startsWith(month))
      monthly = Math.max(monthly, users[userId]?.monthly ?? 0);
  }
  return { daily: usage[date]?.[userId]?.daily ?? 0, monthly };
}
function getAIUsage(userId, rawTier) {
  const { tier, limits } = tierAndLimits(rawTier);
  const usage = currentUsage(readUsage(), today(), userId);
  return { used: usage.daily, daily: usage.daily, monthly: usage.monthly, limits, tier };
}
function aiRateLimit(req, res, next) {
  const user = req.user;
  if (!user?.userId) {
    res.status(401).json({ success: false, error: "Authentication required" });
    return;
  }
  const date = today();
  const usage = readUsage();
  const { limits } = tierAndLimits(user.tier);
  const current = currentUsage(usage, date, user.userId);
  if (current.daily >= limits.daily || current.monthly >= limits.monthly) {
    res.status(429).json({ success: false, error: "AI generation limit reached", usage: { ...current, limits } });
    return;
  }
  if (!usage[date])
    usage[date] = {};
  usage[date][user.userId] = { daily: current.daily + 1, monthly: current.monthly + 1 };
  writeUsage(usage);
  next();
}

