var PROCEDURAL_SUBJECT_NAMES = new Set([
  "sunflower",
  "bird",
  "bird on branch",
  "branch bird",
  "lunar moth",
  "luna moth",
  "butterfly",
  "rose",
  "heart",
  "love",
  "star",
  "stars",
  "peony",
  "bouquet",
  "flower bouquet",
  "pink flower"
]);
function shouldUseProceduralPattern(prompt) {
  const normalized = prompt.toLowerCase().replace(/[^a-z0-9\s]/g, " ").replace(/\s+/g, " ").trim();
  const withoutArticle = normalized.replace(/^(?:a|an|the)\s+/, "");
  return PROCEDURAL_SUBJECT_NAMES.has(withoutArticle);
}
