async function renderMockArtworkSvg(layers, size) {
  const parts = [
    `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 400 400">`,
    `<rect x="0" y="0" width="400" height="400" fill="#ffffff"/>`
  ];
  for (const layer of layers) {
    if (layer.id === "bg")
      continue;
    const cx2 = layer.x + layer.width / 2;
    const cy2 = layer.y + layer.height / 2;
    parts.push(`<g transform="translate(${cx2},${cy2}) rotate(${layer.rotation || 0})">` + `<rect x="${-layer.width / 2}" y="${-layer.height / 2}" width="${layer.width}" height="${layer.height}" ` + `rx="${Math.min(18, layer.width / 4)}" fill="${layer.color}"/>` + `</g>`);
  }
  parts.push(`</svg>`);
  return sharp5(Buffer.from(parts.join(""))).png().toBuffer();
}
