// src/infrastructure/services/collagePdfExporter.ts
var PAGE2 = { width: 595, height: 842 };
var MARGIN2 = 40;
var CONTENT_WIDTH2 = PAGE2.width - MARGIN2 * 2;
async function generateCollagePatternPdf(opts) {
  return new Promise((resolve2, reject) => {
    const doc = new PDFDocument({ size: [PAGE2.width, PAGE2.height], margin: MARGIN2 });
    const chunks = [];
    doc.on("data", (chunk) => chunks.push(chunk));
    doc.on("end", () => resolve2(Buffer.concat(chunks)));
    doc.on("error", (err) => reject(err));
    const canvasW = opts.canvasWidth || 400;
    const canvasH = opts.canvasHeight || 400;
    const patternAreaWidth = CONTENT_WIDTH2 - 120;
    const patternAreaHeight = PAGE2.height - 320;
    const scaleX = patternAreaWidth / canvasW;
    const scaleY = patternAreaHeight / canvasH;
    const scale = Math.min(scaleX, scaleY, 1.2);
    const patternW = canvasW * scale;
    const patternH = canvasH * scale;
    const patternX = MARGIN2 + 50;
    const patternY = 250;
    doc.font("Helvetica-Bold").fontSize(18).text("StitchWise Studio", MARGIN2, 30, { align: "center", width: CONTENT_WIDTH2 });
    doc.font("Helvetica").fontSize(12).fillColor("#666").text("Collage Quilt Pattern", MARGIN2, 52, { align: "center", width: CONTENT_WIDTH2 }).fillColor("#000");
    doc.moveTo(MARGIN2, 72).lineTo(PAGE2.width - MARGIN2, 72).stroke("#e2e8f0");
    let y = 82;
    doc.font("Helvetica-Bold").fontSize(10).text("Pattern:", MARGIN2, y, { continued: true }).font("Helvetica").text(` ${opts.name || "Untitled Collage"}`);
    y += 16;
    doc.font("Helvetica-Bold").fontSize(10).text("Block Size:", MARGIN2, y, { continued: true }).font("Helvetica").text(` ${opts.blockSize}" \xD7 ${opts.blockSize}"`);
    y += 16;
    doc.font("Helvetica-Bold").fontSize(10).text("Pieces:", MARGIN2, y, { continued: true }).font("Helvetica").text(` ${opts.regions.length}`);
    y = 130;
    doc.font("Helvetica-Bold").fontSize(13).text("Pattern Outline", MARGIN2, y);
    const bgX = patternX - 5;
    const bgY = patternY - 5;
    doc.rect(bgX, bgY, patternW + 10, patternH + 10).fillAndStroke("#fafafa", "#ccc");
    for (const r of opts.regions) {
      const rx = patternX + r.x * scale;
      const ry = patternY + r.y * scale;
      const rw = r.width * scale;
      const rh = r.height * scale;
      doc.rect(rx, ry, rw, rh).fillAndStroke("#fff", "#333");
      const fontSize = Math.max(7, Math.min(rw, rh) * 0.35);
      doc.font("Helvetica-Bold").fontSize(fontSize).fillColor("#333").text(String(r.number), rx + rw / 2 - fontSize * 0.3, ry + rh / 2 - fontSize * 0.35, { width: rw, align: "center" });
    }
    const guideY = patternY + patternH + 20;
    doc.font("Helvetica-Bold").fontSize(13).fillColor("#000").text("Color Guide", MARGIN2, guideY);
    doc.font("Helvetica").fontSize(9).fillColor("#666").text("Suggested fabric colors for each numbered piece.", MARGIN2, guideY + 16);
    let tableY = guideY + 34;
    const colX = [MARGIN2, MARGIN2 + 30, MARGIN2 + 50, MARGIN2 + 70];
    doc.font("Helvetica-Bold").fontSize(8).fillColor("#000");
    doc.text("#", colX[0], tableY);
    doc.text("Swatch", colX[1], tableY);
    doc.text("Fabric", colX[2], tableY);
    doc.moveTo(MARGIN2, tableY + 11).lineTo(PAGE2.width - MARGIN2, tableY + 11).stroke("#e2e8f0");
    tableY += 14;
    const seenColors = new Map;
    for (const r of opts.regions) {
      if (!seenColors.has(r.suggestedHex)) {
        seenColors.set(r.suggestedHex, r);
      }
    }
    const uniqueColors = Array.from(seenColors.values());
    doc.font("Helvetica").fontSize(8);
    for (const c of uniqueColors) {
      if (tableY > PAGE2.height - 60)
        break;
      doc.fillColor("#000").text(String(c.number), colX[0], tableY);
      doc.rect(colX[1], tableY, 12, 12).fillAndStroke(c.suggestedHex, "#999");
      doc.fillColor("#000").text(c.suggestedColor, colX[2], tableY + 1);
      tableY += 16;
    }
    const cutY = Math.max(tableY + 20, guideY + 120);
    doc.moveTo(MARGIN2, cutY).lineTo(PAGE2.width - MARGIN2, cutY).stroke("#e2e8f0");
    doc.font("Helvetica-Bold").fontSize(13).fillColor("#000").text("Cutting Instructions", MARGIN2, cutY + 10);
    const instructions = [
      "1. Print this pattern at 100% scale (do not scale to fit).",
      `2. The pattern is designed for a ${opts.blockSize}" \xD7 ${opts.blockSize}" finished block.`,
      "3. Cut out each numbered piece along the solid outline.",
      '4. Trace each piece onto your chosen fabric, adding \xBC" seam allowance on all sides.',
      "5. Use the Color Guide above for fabric suggestions, or choose your own!",
      "6. Piece the sections together following the number layout as a map.",
      "7. Press seams open and square up to finish."
    ];
    doc.font("Helvetica").fontSize(9).fillColor("#333");
    let instY = cutY + 28;
    for (const line of instructions) {
      doc.text(line, MARGIN2, instY, { width: CONTENT_WIDTH2 });
      instY += 14;
    }
    doc.font("Helvetica").fontSize(8).fillColor("#999").text(`Generated by StitchWise Studio \u2014 stitchwisestudio.com`, MARGIN2, PAGE2.height - 30, { align: "center", width: CONTENT_WIDTH2 });
    doc.end();
  });
}

