function generateBasicMachineFormat(grid, format, gridSize) {
  const height = grid.length;
  const width = grid[0]?.length ?? 0;
  const stitchSpacing = 2;
  if (format === "dst") {
    const header = Buffer.alloc(512, 32);
    const totalStitches = width * height;
    header.writeUInt16LE(totalStitches & 65535, 20);
    header.writeUInt16LE(totalStitches >> 16 & 65535, 22);
    const stitches = [header];
    for (let r = 0;r < height; r++) {
      const y = r * stitchSpacing;
      for (let c = 0;c < width; c++) {
        if (grid[r][c]?.color && grid[r][c].color !== "#ffffff") {
          const x = c * stitchSpacing;
          const record = Buffer.alloc(3);
          record.writeInt8(Math.min(127, Math.max(-128, x & 255)), 1);
          record.writeInt8(Math.min(127, Math.max(-128, y & 255)), 2);
          stitches.push(record);
        }
      }
      const colorChange = Buffer.from([0, 0, 195]);
      stitches.push(colorChange);
    }
    stitches.push(Buffer.from([0, 0, 243]));
    return Buffer.concat(stitches);
  }
  if (format === "pes") {
    const header = Buffer.alloc(256, 0);
    Buffer.from("#PES0001").copy(header);
    return Buffer.concat([header, Buffer.from(`StitchWise pattern ${gridSize}x${gridSize}`, "ascii")]);
  }
  return Buffer.from([]);
}
