class PrismaMarketplaceRepo {
  prisma;
  constructor(prisma) {
    this.prisma = prisma;
  }
  async create(input, tags) {
    const record = await this.prisma.marketplaceListing.create({
      data: {
        designerId: input.designerId,
        name: input.name,
        description: input.description ?? "",
        price: input.price ?? 0,
        visibility: input.visibility ?? "PUBLIC",
        tags,
        stitchFile: input.stitchFile ?? null,
        thumbnail: input.thumbnail ?? null
      }
    });
    return this.toDomain(record);
  }
  async getById(id) {
    const record = await this.prisma.marketplaceListing.findUnique({ where: { id } });
    return record ? this.toDomain(record) : null;
  }
  async listByDesigner(designerId) {
    const records = await this.prisma.marketplaceListing.findMany({
      where: { designerId },
      orderBy: { updatedAt: "desc" }
    });
    return records.map((r) => this.toDomain(r));
  }
  async listPublic(options) {
    const where = { visibility: "PUBLIC" };
    if (options?.tags && options.tags.length > 0) {
      where.AND = options.tags.map((tag) => ({
        tags: { contains: tag }
      }));
    }
    if (options?.search) {
      where.OR = [
        { name: { contains: options.search } },
        { description: { contains: options.search } }
      ];
    }
    const records = await this.prisma.marketplaceListing.findMany({
      where,
      orderBy: { createdAt: "desc" }
    });
    return records.map((r) => this.toDomain(r));
  }
  async update(id, designerId, input, tags) {
    const data = {};
    if (input.name !== undefined)
      data.name = input.name;
    if (input.description !== undefined)
      data.description = input.description;
    if (input.price !== undefined)
      data.price = input.price;
    if (input.visibility !== undefined)
      data.visibility = input.visibility;
    if (tags !== undefined)
      data.tags = tags;
    if (input.stitchFile !== undefined)
      data.stitchFile = input.stitchFile;
    if (input.thumbnail !== undefined)
      data.thumbnail = input.thumbnail;
    const record = await this.prisma.marketplaceListing.update({
      where: { id, designerId },
      data
    });
    return this.toDomain(record);
  }
  async delete(id, designerId) {
    await this.prisma.marketplaceListing.delete({
      where: { id, designerId }
    });
  }
  toDomain(r) {
    return {
      id: r.id,
      designerId: r.designerId,
      name: r.name,
      description: r.description,
      price: r.price,
      visibility: r.visibility,
      tags: JSON.parse(r.tags),
      stitchFile: r.stitchFile,
      thumbnail: r.thumbnail,
      createdAt: r.createdAt,
      updatedAt: r.updatedAt
    };
  }
}
